export function createWorkspaceNavigation(renderState) {
  const panel = createPresencePanel((value) => renderState(value, navigation));
  const navigation = {
    select(channel, mode = "synchronous") { panel.show(channel, mode); },
    hide() { panel.close(); },
  };
  return navigation;
}

